<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$st=$pdo->prepare('INSERT INTO visits(patient_id,doctor_id,visit_type,chief_complaint,diagnosis,notes,status) VALUES(?,?,?,?,?,?,?)');$st->execute([(int)$_POST['patient_id'],($_POST['doctor_id']??'')?:null,$_POST['visit_type'],trim($_POST['chief_complaint']??''),trim($_POST['diagnosis']??''),trim($_POST['notes']??''),'Open']);audit('create','visit',(int)$pdo->lastInsertId());flash('Visit recorded.');redirect('visits.php');}
$patients=$pdo->query('SELECT id,patient_no,full_name FROM patients ORDER BY full_name')->fetchAll();$doctors=$pdo->query("SELECT s.id,s.full_name FROM staff s WHERE s.role IN ('Doctor','Nurse','Midwife') AND s.active=1 ORDER BY s.full_name")->fetchAll();$rows=$pdo->query('SELECT v.*,p.patient_no,p.full_name,s.full_name doctor FROM visits v JOIN patients p ON p.id=v.patient_id LEFT JOIN staff s ON s.id=v.doctor_id ORDER BY v.visit_date DESC LIMIT 100')->fetchAll();admin_header('Visits','visits.php');?><div class="pagehead"><div><h1>Clinical Visits</h1><div class="muted">OPD, emergency and follow-up encounters.</div></div><a class="btn" href="?action=new">Record visit</a></div><?php if(($_GET['action']??'')==='new'):?><div class="card" style="margin-bottom:18px"><h2>Record visit</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Patient</label><select name="patient_id" required><option value="">Select patient</option><?php foreach($patients as $p):?><option value="<?=$p['id']?>" <?=((int)($_GET['patient_id']??0)==$p['id']?'selected':'')?>><?=e($p['patient_no'].' — '.$p['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Clinician</label><select name="doctor_id"><option value="">Select clinician</option><?php foreach($doctors as $d):?><option value="<?=$d['id']?>"><?=e($d['full_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Visit type</label><select name="visit_type"><option>OPD</option><option>Emergency</option><option>Follow-up</option><option>Review</option></select></div><div class="field full"><label>Chief complaint</label><textarea name="chief_complaint"></textarea></div><div class="field"><label>Diagnosis</label><textarea name="diagnosis"></textarea></div><div class="field"><label>Clinical notes</label><textarea name="notes"></textarea></div></div><button style="margin-top:14px">Save visit</button></form></div><?php endif;?><div class="card table-wrap"><table class="table"><tr><th>Date</th><th>Patient</th><th>Type</th><th>Clinician</th><th>Diagnosis</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['visit_date'])?></td><td><a href="patient.php?id=<?=$r['patient_id']?>"><?=e($r['patient_no'].' — '.$r['full_name'])?></a></td><td><?=e($r['visit_type'])?></td><td><?=e($r['doctor'])?></td><td><?=e($r['diagnosis'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></table></div><?php admin_footer();
